const results = [];

const timeRange = $input.all()[0].json;
const startDate = new Date(timeRange['start_date']);
const endDate = new Date(timeRange['end_date']); // Fixed typo in key name 'end _date'

// Set time to 00:00:00 to avoid daylight saving time offset issues
startDate.setHours(0, 0, 0, 0);
endDate.setHours(0, 0, 0, 0);

const currentDate = new Date(startDate);

while (currentDate <= endDate) {
  const year = currentDate.getFullYear();
  const month = currentDate.getMonth() + 1;
  const dayOfWeek = currentDate.getDay() === 0 ? 7 : currentDate.getDay(); // Monday=1, Sunday=7
  const quarter = Math.floor((month - 1) / 3) + 1;

  const isWeekend = dayOfWeek === 6 || dayOfWeek === 7 ? 1 : 0;

  // Format YYYY-MM-DD using local time
  const dayStr = String(currentDate.getDate()).padStart(2, '0');
  const monthStr = String(month).padStart(2, '0');
  const dateKey = `${year}-${monthStr}-${dayStr}`;

  results.push({
    date_key: dateKey,
    year,
    quarter,
    month,
    day_of_week: dayOfWeek,
    is_weekend: isWeekend,
    is_trading_day: isWeekend ? 0 : 1
  });

  // Increment by 1 day
  currentDate.setDate(currentDate.getDate() + 1);
}

return results.map(r => ({ json: r }));

